const LONG_OPTIONS = ['--help', '--payload'];

function basename(path) {
  if (!path) {
    return 'test1.mjs';
  }

  const normalized = path.replace(/\\/gu, '/');
  const lastSlash = normalized.lastIndexOf('/');
  return lastSlash === -1 ? normalized : normalized.slice(lastSlash + 1);
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --payload PAYLOAD\n`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}\noptions:\n  -h, --help         show this help message and exit\n  --payload PAYLOAD\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}${programName}: error: ${message}\n`;
}

function resolveLongOption(optionName) {
  if (LONG_OPTIONS.includes(optionName)) {
    return optionName;
  }

  const matches = LONG_OPTIONS.filter((candidate) => candidate.startsWith(optionName));
  return matches.length === 1 ? matches[0] : null;
}

function isNegativeNumberLike(token) {
  return /^-\d+$|^-\d*\.\d+$/u.test(token);
}

export function parseCliArgs(argv, scriptPath) {
  const programName = basename(scriptPath);
  const extras = [];
  let payloadValue = '';
  let hasPayload = false;
  let expectingPayloadValue = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (expectingPayloadValue) {
      if (token.startsWith('-') && !isNegativeNumberLike(token)) {
        return {
          kind: 'error',
          exitCode: 2,
          text: formatError(programName, 'argument --payload: expected one argument'),
        };
      }

      payloadValue = token;
      hasPayload = true;
      expectingPayloadValue = false;
      continue;
    }

    if (token === '-h') {
      return { kind: 'help', exitCode: 0, text: formatHelp(programName) };
    }

    if (token === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const explicitValue = equalsIndex === -1 ? '' : token.slice(equalsIndex + 1);
      const resolved = resolveLongOption(optionName);

      if (resolved === '--help') {
        if (equalsIndex !== -1) {
          return {
            kind: 'error',
            exitCode: 2,
            text: formatError(programName, `argument -h/--help: ignored explicit argument '${explicitValue}'`),
          };
        }

        return { kind: 'help', exitCode: 0, text: formatHelp(programName) };
      }

      if (resolved === '--payload') {
        if (equalsIndex !== -1) {
          payloadValue = explicitValue;
          hasPayload = true;
          continue;
        }

        expectingPayloadValue = true;
        continue;
      }
    }

    extras.push(token);
  }

  if (expectingPayloadValue) {
    return {
      kind: 'error',
      exitCode: 2,
      text: formatError(programName, 'argument --payload: expected one argument'),
    };
  }

  if (!hasPayload) {
    return {
      kind: 'error',
      exitCode: 2,
      text: formatError(programName, 'the following arguments are required: --payload'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: formatError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    exitCode: 0,
    values: {
      payload: payloadValue,
    },
  };
}

