import { parseCliArgs } from './lib/cli/argparse_compat.mjs';
import { encodeJwt } from './lib/jwt/encode.mjs';

const SECRET = 'my_secret_key';

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const parsed = parseCliArgs(argv, scriptPath);

  if (parsed.kind === 'help') {
    process.stdout.write(parsed.text);
    return parsed.exitCode;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(parsed.text);
    return parsed.exitCode;
  }

  const token = encodeJwt(parsed.values.payload, SECRET);
  process.stdout.write(`${token}\n`);
  return 0;
}

const exitCode = main();

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

